'use strict';

if (typeof window !== 'undefined') {
  try {
    if (typeof partyForm === 'function') {
      window._partyFormImpl = partyForm;
      window.partyForm = partyForm;
    }
  } catch (e) {}
}

function bindDocumentNumberPreview(form, options) {
  const numberInput = form.querySelector(options.number);
  if (!numberInput) return;

  let latestRequest = 0;
  let lastSuggestedNumber = numberInput.value || '';
  let userManuallyEdited = false;

  numberInput.addEventListener('input', () => {
    userManuallyEdited = (numberInput.value.trim() !== lastSuggestedNumber);
  });

  const refresh = async (forceUpdate = false) => {
    const requestId = ++latestRequest;
    const params = new URLSearchParams();
    [
      ['date', options.date],
      ['customer_type', options.customerType],
      ['branch', options.branch],
      ['location', options.location],
      ['series', options.series],
      ['series_id', options.seriesId]
    ].forEach(([name, selector]) => {
      const el = selector ? form.querySelector(selector) : null;
      const value = el ? el.value : '';
      if (value) params.set(name, value);
    });
    const selectedSeriesId = options.series
      ? form.querySelector(options.series)?.selectedOptions?.[0]?.dataset.id
      : '';
    if (selectedSeriesId) params.set('series_id', selectedSeriesId);
    const businessLocation = options.businessLocation
      ? form.querySelector(options.businessLocation)
      : null;
    if (businessLocation && businessLocation.value) {
      params.set('business_location_id', businessLocation.value);
    }
    const gstin = options.getGstin ? options.getGstin() : '';
    if (gstin) params.set('gstin', gstin);

    try {
      const preview = await api(`lookup/${options.endpoint}/?${params.toString()}`);
      if (requestId !== latestRequest || !preview || !preview.next_number) return;
      if (forceUpdate || !numberInput.value || !userManuallyEdited || numberInput.value === lastSuggestedNumber) {
        numberInput.value = preview.next_number;
        lastSuggestedNumber = preview.next_number;
        userManuallyEdited = false;
      }
    } catch (error) {
      if (requestId === latestRequest) {
        console.warn(`Could not refresh document number preview: ${error.message}`);
      }
    }
  };

  [options.date, options.customerType, options.location, options.businessLocation, options.party]
    .filter(Boolean)
    .forEach(selector => {
      form.querySelector(selector)?.addEventListener('change', () => refresh(false));
    });

  if (options.series) {
    form.querySelector(options.series)?.addEventListener('change', () => {
      refresh(true);
    });
  }
  if (options.seriesId) {
    form.querySelector(options.seriesId)?.addEventListener('change', () => {
      refresh(true);
    });
  }

  if (options.branch) {
    const branchEl = form.querySelector(options.branch);
    const seriesEl = options.series ? form.querySelector(options.series) : null;
    const onBranchChange = () => {
      if (branchEl && seriesEl && branchEl.value.trim()) {
        const bVal = branchEl.value.trim().toLowerCase();
        const match = Array.from(seriesEl.options).find(opt => {
          const b = (opt.dataset.branch || '').toLowerCase();
          const l = (opt.dataset.location || '').toLowerCase();
          return (b && b === bVal) || (l && l === bVal);
        });
        if (match && seriesEl.value !== match.value) {
          seriesEl.value = match.value;
          refresh(true);
          return;
        }
      }
      refresh(false);
    };

    let branchTimer;
    branchEl?.addEventListener('input', () => {
      clearTimeout(branchTimer);
      branchTimer = setTimeout(onBranchChange, 250);
    });
    branchEl?.addEventListener('change', onBranchChange);
  }

  void refresh(false);
}
window.bindDocumentNumberPreview = bindDocumentNumberPreview;

function defaultBusinessLocationId(locations, existingId = null, isNew = false) {
  const options = Array.isArray(locations) ? locations : [];
  const existing = options.find(item => String(item.id) === String(existingId || ''));
  if (existing) return String(existing.id);
  if (isNew) {
    const defaultLocation = options.find(item => item.is_default);
    return defaultLocation ? String(defaultLocation.id) : '';
  }
  return '';
}

function businessLocationSelectHtml(locations, selectedId, id) {
  const options = Array.isArray(locations) ? locations : [];
  return `<label class="transaction-card-field">
    <span class="transaction-card-label" id="${esc(id)}-label">Branch</span>
    <select class="in" id="${esc(id)}" name="branch_id" aria-labelledby="${esc(id)}-label">
      <option value="">${options.length ? 'Select Branch...' : 'No branches available'}</option>
      ${options.map(item => `<option value="${item.id}" ${String(item.id) === String(selectedId || '') ? 'selected' : ''}>${esc(item.name)}${item.is_default ? ' (Default)' : ''}</option>`).join('')}
    </select>
  </label>`;
}

function bindBusinessLocationSelection(form, selector, locations, legacyLocationSelector = null) {
  const select = form.querySelector(selector);
  const legacyLocation = legacyLocationSelector
    ? form.querySelector(legacyLocationSelector)
    : null;
  if (!select) return;
  select.addEventListener('change', () => {
    const selected = locations.find(item => String(item.id) === String(select.value));
    if (legacyLocation) legacyLocation.value = selected ? selected.name : '';
  });
}

function selectedBusinessLocationId(form, selector) {
  const value = form.querySelector(selector)?.value || '';
  return /^\d+$/.test(value) ? Number(value) : null;
}

function transactionSeriesForBusinessLocation(series, locations, locationId) {
  const options = Array.isArray(series) ? series : [];
  const location = (Array.isArray(locations) ? locations : [])
    .find(item => String(item.id) === String(locationId || ''));
  const assignedIds = new Set((location?.transaction_series_ids || []).map(String));
  return options.filter(item => {
    if (item.business_location_id && String(item.business_location_id) !== String(locationId || '')) {
      return false;
    }
    if (!locationId && item.business_location_id) return false;
    return !assignedIds.size || assignedIds.has(String(item.id));
  });
}

function chooseTransactionSeries(options, location, preferredName = '', preferredId = '', preferBranchDefault = false) {
  const candidates = Array.isArray(options) ? options : [];
  const byId = id => candidates.find(item => String(item.id) === String(id || ''));
  const byName = name => candidates.find(item => item.name === name);
  return (preferBranchDefault && byId(location?.default_transaction_series_id)) ||
    byName(preferredName) ||
    byId(preferredId) ||
    byId(location?.default_transaction_series_id) ||
    candidates.find(item => item.is_default) ||
    candidates[0] ||
    null;
}

function transactionSeriesOptionsHtml(options, selectedId) {
  if (!options.length) {
    return '<option value="">No active transaction series available</option>';
  }
  return options.map(item =>
    `<option value="${esc(item.name)}" data-id="${item.id}" data-branch="${esc(item.branch || '')}" data-location="${esc(item.location || '')}" data-business-location-id="${item.business_location_id || ''}" ${String(selectedId) === String(item.id) ? 'selected' : ''}>${esc(item.name)}</option>`
  ).join('');
}

function bindTransactionSeriesToBusinessLocation(form, seriesSelector, locationSelector, series, locations) {
  const select = form.querySelector(seriesSelector);
  const branchSelect = form.querySelector(locationSelector);
  if (!select || !branchSelect) return;
  branchSelect.addEventListener('change', () => {
    const location = (Array.isArray(locations) ? locations : [])
      .find(item => String(item.id) === String(branchSelect.value || ''));
    const options = transactionSeriesForBusinessLocation(series, locations, branchSelect.value);
    const currentOption = select.selectedOptions[0];
    const selected = chooseTransactionSeries(
      options, location, currentOption?.value || '', currentOption?.dataset.id || '', true
    );
    select.innerHTML = transactionSeriesOptionsHtml(options, selected?.id);
  });
}

function selectedNumberingSeriesId(form, selector) {
  const id = form.querySelector(selector)?.selectedOptions?.[0]?.dataset.id || '';
  return /^\d+$/.test(id) ? Number(id) : null;
}

const Modal = (() => {
  const stack = [];

  function open({ title, body, footer = '', wide = false, onClose, dialog = false, onScreen = null, headerActions = '' }) {
    const pg = $('#pg');
    const hasFormElements = Boolean(body && (
      body.includes('<form') ||
      body.includes('type="submit"') ||
      body.includes('class="fe"') ||
      body.includes('party-form-wrap') ||
      body.includes('convo-item-modal')
    ));
    const renderOnScreen = (onScreen === true || (hasFormElements && !dialog && onScreen !== false)) && Boolean(pg);

    if (renderOnScreen && pg) {
      const existing = pg.querySelector('.on-screen-form-view');
      if (existing) {
        existing.remove();
      }
      const prevChildren = Array.from(pg.children);
      prevChildren.forEach(child => {
        if (child._origDisplay === undefined) {
          child._origDisplay = child.style.display;
        }
        child.style.display = 'none';
      });

      const el = document.createElement('div');
      el.className = 'on-screen-form-view';
      el.setAttribute('role', 'region');
      el.setAttribute('aria-label', title || 'Form');

      el.innerHTML = `
        <div class="on-screen-form-header">
          <div class="on-screen-header-left">
            <button type="button" class="btn on-screen-back-btn" data-close title="Back" aria-label="Back">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M19 12H5M12 19l-7-7 7-7"/></svg>
            </button>
            <h1 class="on-screen-form-title">${esc(title)}</h1>
          </div>
          ${headerActions ? `<div class="on-screen-header-right" style="display:flex;align-items:center;gap:12px;">${headerActions}</div>` : ''}
        </div>
        <div class="on-screen-form-body-wrap">
          <div class="mb on-screen-form-content ${wide ? 'wide' : ''}">${body}</div>
        </div>
        <div class="on-screen-sticky-footer">
          ${footer ? footer : '<button type="button" class="btn" data-close>Cancel</button>'}
        </div>
      `;

      pg.appendChild(el);
      window.scrollTo({ top: 0, behavior: 'instant' });

      const m = {
        el,
        body: $('.mb', el),
        beforeClose: null,
        prev: document.activeElement,
        onScreen: true,
        closed: false
      };

      m.close = () => {
        if (m.closed) return;
        m.closed = true;
        const i = stack.indexOf(m);
        if (i >= 0) stack.splice(i, 1);
        el.remove();
        if (onScreen && location.hash.includes('/new')) {
          const baseHash = location.hash.replace(/\/new.*$/, '');
          if (location.hash !== baseHash) {
            location.hash = baseHash;
            if (onClose) onClose();
            return;
          }
        }
        prevChildren.forEach(child => {
          child.style.display = child._origDisplay || '';
        });
        if (!prevChildren.length && window.PAGE && window.PAGE.reload) {
          window.PAGE.reload();
        }
        if (onClose) onClose();
        if (m.prev && m.prev.isConnected && m.prev.focus) m.prev.focus();
      };

      m.request = async () => {
        if (m.requesting) return;
        m.requesting = true;
        try {
          if (m.beforeClose && !(await m.beforeClose())) return;
          m.close();
        } finally {
          m.requesting = false;
        }
      };

      el.addEventListener('click', e => {
        if (e.target.closest('[data-close]')) {
          e.preventDefault();
          e.stopPropagation();
          m.request();
        }
      });

      stack.push(m);
      const f = el.querySelector('input:not([type=hidden]):not([disabled]),select,textarea');
      if (f) f.focus();
      return m;
    }

    if (!renderOnScreen && pg && pg.querySelector('.on-screen-form-view') && !dialog) {
      const existing = pg.querySelector('.on-screen-form-view');
      const f = existing.querySelector('input:not([type=hidden]):not([disabled]),select,textarea');
      if (f) f.focus();
      return { el: existing, body: $('.mb', existing), close: () => {}, closed: false };
    }

    const el = document.createElement('div');
    el.className = 'mo';
    el.innerHTML = `<div class="md ${wide ? 'wide' : ''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="mh"><h2>${esc(title)}</h2><div style="display:flex;align-items:center;gap:10px;margin-left:auto;">${headerActions || ''}<button type="button" class="x" data-close aria-label="Close">✕</button></div></div><div class="mb">${body}</div>${footer ? `<div class="mf">${footer}</div>` : ''}</div>`;
    $('#modal-root').appendChild(el);
    const m = { el, body: $('.mb', el), beforeClose: null, prev: document.activeElement, onScreen: false, closed: false };
    m.close = () => {
      if (m.closed) return;
      m.closed = true;
      const i = stack.indexOf(m); if (i >= 0) stack.splice(i, 1);
      el.remove();
      if (!stack.some(x => !x.onScreen)) document.body.classList.remove('modal-open');
      if (onClose) onClose();
      if (m.prev && m.prev.isConnected && m.prev.focus) m.prev.focus();
    };
    m.request = async () => {
      if (m.requesting) return;
      m.requesting = true;
      try {
        if (m.beforeClose && !(await m.beforeClose())) return;
        m.close();
      } finally {
        m.requesting = false;
      }
    };
    el.addEventListener('click', e => {
      if (e.target.closest('[data-close]')) {
        e.preventDefault();
        e.stopPropagation();
        m.request();
      }
    });
    stack.push(m);
    document.body.classList.add('modal-open');
    const f = el.querySelector('input:not([type=hidden]):not([disabled]),select,textarea') || el.querySelector('.mf .p');
    if (f) f.focus();
    return m;
  }

  document.addEventListener('keydown', e => {
    if (!stack.length) return;
    const top = stack[stack.length - 1];
    if (e.key === 'Escape') { e.stopImmediatePropagation(); top.request(); }
    if (e.key === 'Tab' && !top.onScreen) {
      const f = $$('a[href],button:not([disabled]),input:not([disabled]):not([type=hidden]),select:not([disabled]),textarea:not([disabled])', top.el);
      if (!f.length) return;
      const first = f[0], last = f[f.length - 1];
      if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
      else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
    }
  });

  window.addEventListener('popstate', () => {
    while (stack.length) {
      const top = stack[stack.length - 1];
      top.close();
    }
  });
  window.addEventListener('hashchange', () => {
    while (stack.length) {
      const top = stack[stack.length - 1];
      top.close();
    }
  });

  return { open, get top() { return stack[stack.length - 1]; }, count: () => stack.length, stack };
})();

function confirmBox({ title, message, okText = 'Confirm', danger = false }) {
  return new Promise(resolve => {
    let done = false;
    const fin = v => { if (!done) { done = true; resolve(v); } };
    const m = Modal.open({
      title, body: `<p>${esc(message)}</p>`, onClose: () => fin(false),

      footer: `<button class="btn" type="button" data-close>Cancel</button><button class="btn ${danger ? 'd' : 'p'}" type="button" data-ok>${esc(okText)}</button>`,
    });
    $('[data-ok]', m.el).addEventListener('click', () => { fin(true); m.close(); });
    $('[data-ok]', m.el).focus();
  });
}

let uid = 0;
var opts = (typeof window !== "undefined" && window.opts) ? window.opts : ((list, sel) => (list || []).map(o => { const [v, l] = Array.isArray(o) ? o : [o, o]; const selected = Array.isArray(sel) ? sel.map(String).includes(String(v)) : String(v) === String(sel == null ? '' : sel); return `<option value="${esc(v)}"${selected ? ' selected' : ''}>${esc(l)}</option>`; }).join(''));
function fld(o) {
  const id = 'i' + (++uid), v = o.value == null ? '' : o.value, req = o.req ? ' required aria-required="true"' : '', at = o.attrs || '';
  let ctl;
  if (o.type === 'checkbox') return `<div class="zb-form-row fg ${o.col || ''}"><div class="zb-form-label"></div><div class="zb-form-ctrl"><label class="ck"><input type="checkbox" name="${o.name}" ${v ? 'checked' : ''} ${at}> ${esc(o.label)}</label><div class="er" data-err="${o.name}" role="alert"></div></div></div>`;
  if (o.type === 'select') {
    let optionsList = Array.isArray(o.opts) ? [...o.opts] : [];
    const n = (o.name || '').toLowerCase();
    const l = (o.label || '').toLowerCase();
    const hasEmptyFirst = optionsList.length > 0 && ((Array.isArray(optionsList[0]) ? optionsList[0][0] : optionsList[0]) === '');
    const insertIdx = hasEmptyFirst ? 1 : 0;

    const addOptionIfNotPresent = (val, text) => {
      if (!optionsList.some(item => (Array.isArray(item) ? item[0] : item) === val)) {
        optionsList.splice(insertIdx, 0, [val, text]);
      }
    };

    if (n === 'customer' || n === 'customer_id' || l.includes('customer')) {
      addOptionIfNotPresent('__new_customer__', '+ Add New Customer…');
    } else if (n === 'vendor' || n === 'vendor_id' || l.includes('vendor')) {
      addOptionIfNotPresent('__new_vendor__', '+ Add New Vendor…');
    } else if (n === 'item' || n === 'item_id' || l.includes('item') || l.includes('product')) {
      addOptionIfNotPresent('__new_item__', '+ Add New Item…');
    } else if (n === 'salesperson' || n === 'salesperson_id' || l.includes('salesperson') || l.includes('sales person')) {
      addOptionIfNotPresent('__new_salesperson__', '+ Add New Salesperson…');
    } else if (n.includes('warehouse') || l.includes('warehouse')) {
      addOptionIfNotPresent('__new_warehouse__', '+ Add New Warehouse…');
    } else if (n.includes('employee') || l.includes('employee')) {
      addOptionIfNotPresent('__new_employee__', '+ Add New Employee…');
    } else if (n.includes('category') || l.includes('category')) {
      addOptionIfNotPresent('__new_category__', '+ Add New Category…');
    } else if (n.includes('price') || l.includes('price list')) {
      addOptionIfNotPresent('__new_pricelist__', '+ Add New Price List…');
    } else if (n.includes('account') || l.includes('account')) {
      addOptionIfNotPresent('__new_account__', '+ Add New Account…');
    } else if (n.includes('project') || l.includes('project')) {
      addOptionIfNotPresent('__new_project__', '+ Add New Project…');
    }
    ctl = `<select class="in" id="${id}" name="${o.name}"${req} ${at}>${opts(optionsList, v)}</select>`;
  }
  else if (o.type === 'textarea') ctl = `<textarea class="in" id="${id}" name="${o.name}" rows="${o.rows || 2}" maxlength="${o.max || 2000}" ${at}>${esc(v)}</textarea>`;
  else ctl = `<input class="in" id="${id}" name="${o.name}" type="${o.type || 'text'}" value="${esc(v)}"${o.ph ? ` placeholder="${esc(o.ph)}"` : ''}${req} ${at}>`;
  return `<div class="zb-form-row fg ${o.type === 'textarea' ? 'align-top' : ''} ${o.col || ''}"><label class="zb-form-label" for="${id}">${esc(o.label)}${o.req ? ' <span class="rq">*</span>' : ''}</label><div class="zb-form-ctrl">${ctl}<div class="er" data-err="${o.name}" role="alert"></div>${o.help ? `<div class="hp" style="font-size:11px;color:var(--tx-muted);margin-top:2px;">${esc(o.help)}</div>` : ''}</div></div>`;
}

async function salespersonModal(onDone, onCancel) {
  let isSaved = false;
  formModal({
    title: 'New Salesperson',
    dialog: true,
    wide: false,
    onClose: () => {
      if (!isSaved && typeof onCancel === 'function') {
        try { onCancel(); } catch (e) {}
      }
    },
    body: `
      <div class="zb-form-wrap">
        ${fld({ name: 'name', label: 'Salesperson Name', req: true, ph: 'e.g. Rahul Sharma' })}
        ${fld({ name: 'email', label: 'Email Address', type: 'email', req: false, ph: 'rahul@example.com' })}
        ${fld({ name: 'phone', label: 'Phone Number', req: false, ph: '+91 9876543210' })}
      </div>
    `,
    onSubmit: async d => {
      const name = (d.name || '').trim();
      const email = (d.email || '').trim();
      const nameValid = /^[A-Za-z .'-]+$/.test(name);
      const emailValid = !email || /^[^\s@]+@[^\s@]+\.[A-Za-z]{2,63}$/.test(email);
      if (!nameValid) throw new ApiErr(400, { name: 'Enter a valid name' }, 'Enter a valid name');
      if (!emailValid) throw new ApiErr(400, { email: 'Enter a valid email address' }, 'Enter a valid email address');
      const res = await api('salespersons/', { method: 'POST', body: d });
      isSaved = true;
      toast(`Salesperson "${res.name || name}" added successfully!`, 'ok');
      if (onDone) onDone(res);
      else refresh();
    }
  });
}
window.salespersonModal = salespersonModal;

