  const rProfileName = rec ? (rec.profile_name || rec.name || '') : '';
  const rOrderNum = rec ? (rec.order_number || '') : '';
  const rRepeatEvery = rec ? (rec.repeat_every != null ? rec.repeat_every : 1) : 1;
